def shell(title, desc, body, variant='hub'):
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Bamboo Solid 2000 Series</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="robots" content="noindex,follow"><link rel="stylesheet" href="assets/site.css"><script defer src="assets/config.js"></script><script defer src="assets/site.js"></script></head><body data-variant="{variant}"><a class="skip" href="#main">Skip to content</a><header class="wrap"><a class="brand" href="index.html">BAMBOO<span>SOLID 2000 SERIES</span></a><nav aria-label="Main"><a href="value.html">The set</a><a href="colors.html">The colors</a><a href="gifts.html">Gifting</a></nav><a class="header-call" href="tel:+14043142100" data-call>404-314-2100 →</a></header>{body}<footer class="wrap"><div class="brand">BAMBOO<span>SOLID 2000 SERIES</span></div><p>Questions? <a href="tel:+14043142100" data-call>404-314-2100</a><br><a href="privacy.html">Privacy</a> · <a href="https://bamboo-solid-2000-series.relentless-a-2737.chatgpt.site">Original collection</a></p><p class="fine">Styled imagery from the original collection site.<br>Confirm exact product appearance and availability when ordering.</p></footer></body></html>'''

for key,(eyebrow,title,desc,color,code,subhead,steps) in variants.items():
 hero_src = 'assets/editorial-model-teal.webp' if key == 'everyday-refresh' else f'assets/color-{color}.webp'
 hero_alt = 'Illustrative generated lifestyle image of the supplied model with teal bedding' if key == 'everyday-refresh' else f'Styled bedroom with {color} bedding from the original collection'
 content=f'''<main id="main"><section class="hero wrap"><div class="hero-copy"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="lede">{desc}</p><a class="button" href="#choose">Choose your set <span>→</span></a><p class="fine">Queen & King · Twelve listed colors · Phone orders</p></div><figure class="hero-art"><img src="{hero_src}" alt="{hero_alt}" width="1400" height="1400" fetchpriority="high"><figcaption>{'Illustrative generated lifestyle scene / Teal inspiration' if key == 'everyday-refresh' else color.replace('-', ' ').title() + ' / a little inspiration for your room'}</figcaption></figure></section>
<section class="facts"><div class="wrap fact-grid"><p><strong>6</strong>pieces per sheet set</p><p><strong>12</strong>listed colors</p><p><strong>2</strong>bed sizes</p><p><strong>$20</strong>listed sheet set price*</p></div></section>
<section class="wrap story"><p class="eyebrow">A considered choice</p><h2>{subhead}</h2><div class="steps">{''.join(f'<article><span>{n}</span><h3>{h}</h3><p>{p}</p></article>' for n,h,p in steps)}</div></section>
<section class="chooser wrap" id="choose"><figure class="product-photo"><img id="selected-image" src="assets/color-{color}.webp" alt="{color.title()} styled bedding preview" width="1400" height="1400" loading="lazy"><figcaption id="image-caption">Styled color inspiration. Confirm the actual product when ordering.</figcaption></figure><div class="product-info"><p class="eyebrow">Your bedroom, your choice</p><h2>Bamboo Solid<br>2000 Series</h2><p class="price">$20 <span>/ sheet set*</span></p><p>Includes 1 fitted sheet, 1 flat sheet, and 4 pillowcases.</p><label for="size">01 / Choose your size</label><select id="size"><option>Queen</option><option>King</option></select><p id="dimensions" class="fine">Queen fitted sheet: 60 × 80 in. Confirm mattress depth by phone.</p><label for="color">02 / Choose your color</label><select id="color">{''.join(f'<option{chr(32)+"selected" if name.lower().replace(' ', '-')==color else ""}>{name}</option>' for name in ['Gold','Teal','Chocolate','White','Burgundy','Charcoal','Navy','Taupe','Sage','Burnt Orange','Blush','Black'])}</select><p id="selection" class="selection" aria-live="polite"></p><a class="button wide" href="tel:+14043142100" data-call data-code="{code}">Call to order <span>→</span></a><p class="fine">404-314-2100 · Mention <strong>{code}</strong><br>*Price shown on the original site. Confirm current pricing, availability, taxes, shipping, and returns before ordering. Selecting options here does not reserve stock or place an order.</p></div></section>
<section class="wrap details-section"><div><p class="eyebrow">Know before you order</p><h2>The details<br>make the difference.</h2><img class="detail-image" src="assets/sheets-closeup-black-burgundy.webp" alt="Close-up of black and burgundy bedding from the original site" width="1400" height="1400" loading="lazy"></div><div class="faq"><details><summary>What is included in the sheet set?</summary><p>One fitted sheet, one flat sheet, and four pillowcases. Pillows are sold separately.</p></details><details><summary>Which sizes are listed?</summary><p>Queen fitted sheet: 60 × 80 inches. King fitted sheet: 76 × 80 inches. Confirm pocket depth and pillowcase dimensions when calling.</p></details><details><summary>What is the fabric composition?</summary><p>Bamboo Solid 2000 Series is the product name. Ask for the current package fiber label before ordering; exact composition and thread count are not verified here.</p></details><details><summary>Can I add pillows?</summary><p>The original site lists Cool Comfort Bamboo Pillows at $40 per Queen set and $50 per King set. Call to confirm current prices and how many pillows are included.</p></details><details><summary>How do I pay and receive my order?</summary><p>Orders are arranged by phone. Confirm accepted payment methods, collection or shipping, delivery timing, and returns before paying. No online payment is collected on this page.</p></details><details><summary>How should I care for my set?</summary><p>Follow the care label on the exact set you receive. Ask about washing and drying instructions before ordering if you have specific requirements.</p></details></div></section>
<section class="closing"><div class="wrap"><p class="eyebrow">Make room for a refresh</p><h2>Start with your<br>favorite color.</h2><a class="button light" href="tel:+14043142100" data-call data-code="{code}">Let’s choose your set <span>→</span></a><p>Call 404-314-2100 · Mention {code}</p></div></section></main><a class="mobile-call" href="tel:+14043142100" data-call data-code="{code}">Call to order · 404-314-2100 →</a>'''
 (dist/f'{key}.html').write_text(shell(title,desc,content,key))

 # Size-specific pages should begin with the advertised size.
